    return [go.Indicator(mode='number',number={'valueformat':',.0f'},value=float(sub.price.sum()),title={'text':'ยอดขาย (บาท)'}),go.Bar(x=menu.menu,y=menu.price),go.Scatter(x=daily.date,y=daily.price,mode='lines+markers')]
